    "ai2.subtitle": "Hai = Human + AI. AI² = Trí Tuệ Thực Tế (Trí tuệ, đạo đức & thẩm định điểm mù AI của con người) × Trí Tuệ Nhân Tạo (Điện toán vô hạn & tốc độ dưới 1 xu) - nơi con người dẫn dắt, kiểm duyệt và bổ khuyết mọi giới hạn nhận thức của máy móc.",
    "ai2.card1Title": "Trí Tuệ Thực Tế: Chỉ Huy Tối Cao & Thẩm Định Điểm Mù AI",
    "ai2.card1Desc": "Con người đóng góp trí tuệ thực tế không thể thay thế: khi AI gặp điểm mù nhận thức, ảo giác hoặc tình huống biên cần đạo đức, chuyên gia con người sẽ tham gia thẩm định, kiểm duyệt và chuẩn hóa dữ liệu - được bảo hộ bởi Passkey sinh trắc học, hạn mức Merkle và khóa dừng khẩn cấp < 400ms.",
    "ai2.card2Title": "Trí Tuệ Nhân Tạo: Thực Thi Siêu Tốc Không Nghỉ",
    "ai2.card2Desc": "Các tác tử AI tự hành thực hiện các khoản thanh toán vi mô nano-cent ($0.0001 - $0.001) trong dưới 400 mili-giây cho mỗi lệnh gọi API hoặc GPU mà không làm nghẽn chuỗi suy luận LLM.",
    "ai2.card3Title": "Cộng Sinh Kinh Tế Hai Chiều: AI Thuê Trí Tuệ Con Người",
    "ai2.card3Desc": "Mô hình kinh tế cộng sinh khép kín: AI trả tiền bản quyền USDT liên tục cho tri thức con người, đồng thời tự động ký quỹ vi thanh toán để thuê con người xác thực thế giới thực, kiểm định điểm mù và gán nhãn chân lý (Reverse Micro-Tasking qua giao thức HTTP x402).",
