    "ai2.badge": "मूल प्रतिमान • मानव + मशीन सहजीविता (AI²)",
    "ai2.title": "AI² प्रतिमान: मानव संप्रभु आदेश, मशीन वेग निष्पादन",
    "ai2.subtitle": "Hai = मानव + AI। AI² = वास्तविक बुद्धिमत्ता (मानवीय नैतिकता, उद्देश्य और ब्लाइंड-स्पॉट ऑडिट) × कृत्रिम बुद्धिमत्ता (अनंत संगणना और सब-सेंट गति) - स्वायत्त प्रणालियों पर मानवीय संप्रभुता स्थापित करना।",
    "ai2.card1Title": "वास्तविक बुद्धिमत्ता: मानव संप्रभु कमान और ब्लाइंड-स्पॉट निरीक्षण",
    "ai2.card1Desc": "मानव अपूरणीय ज्ञान का योगदान करते हैं: जब AI संज्ञानात्मक ब्लाइंड-स्पॉट, मतिभ्रम या नैतिक सीमाओं का सामना करता है, तो मानव विशेषज्ञ ऑडिट, सत्यापन और मॉडरेशन के लिए कदम उठाते हैं - बायोमेट्रिक पासकी, मर्कल खर्च सीमा और < 400ms पैनिक स्विच द्वारा सुरक्षित।",
    "ai2.card2Title": "कृत्रिम बुद्धिमत्ता: उच्च गति निष्पादन",
    "ai2.card2Desc": "स्वायत्त AI एजेंट LLM तर्क लूप को रोके बिना प्रति API या GPU कॉल 400 मिलीसेकंड से कम समय में नैनो-माइक्रो भुगतान ($0.0001 - $0.001) निष्पादित करते हैं।",
    "ai2.card3Title": "दोतरफा आर्थिक सहजीविता: AI मानव बुद्धिमत्ता को काम पर रखता है",
    "ai2.card3Desc": "एक बंद लूप सहजीवी अर्थव्यवस्था: AI मानव ज्ञान रचनाकारों को USDT रॉयल्टी स्ट्रीम करता है, जबकि वास्तविक दुनिया के सत्यापन और ब्लाइंड स्पॉट समाधान के लिए इंसानों को स्वचालित रूप से काम पर रखता है (HTTP x402 के माध्यम से रिवर्स माइक्रो-टास्किंग)।",
